@Test
void trashRestoreAndPermanentDeletionAreDurableAndPreventResurrection() throws Exception {
    var database = Files.createTempFile("ji-host-retention-", ".db");
    try (HostStore store = store(database)) {
        SessionDocument created = store.create("session-1", new ModelRef("profile", "model"), "workspace", NOW);
        SessionDocument named = store.update("session-1", created.revision(),
                document -> document.setName(Optional.of("retained alpha")));
        var trashed = store.trash("session-1", named.revision(), NOW);
        assertTrue(store.load("session-1").isEmpty());
        assertTrue(store.search(HostStore.SearchQuery.firstPage("alpha")).hits().isEmpty());
        assertThrows(io.github.diodeme.ji.host.SessionRetentionException.class,
                () -> store.permanentlyDelete("session-1", trashed.state().revision(), NOW.plusSeconds(1)));
    }
    try (HostStore reopened = store(database)) {
        var restored = reopened.restore("session-1", 2, NOW.plusSeconds(2));
        assertEquals(io.github.diodeme.ji.session.model.CanonicalSessionState.SessionStatus.AVAILABLE,
                restored.state().status());
        assertFalse(reopened.search(HostStore.SearchQuery.firstPage("alpha")).hits().isEmpty());
        var trashedAgain = reopened.trash("session-1", restored.state().revision(), NOW.plusSeconds(3));
        var tombstone = reopened.permanentlyDelete("session-1", trashedAgain.state().revision(),
                NOW.plusSeconds(3).plus(java.time.Duration.ofDays(30)));
        assertEquals("session-1", tombstone.sessionId());
        assertTrue(reopened.load("session-1").isEmpty());
        assertThrows(io.github.diodeme.ji.host.SessionRetentionException.class,
                () -> reopened.create("session-1", new ModelRef("profile", "model"), "workspace", NOW));
    }
    try (HostStore reopened = store(database)) {
        assertEquals("session-1", reopened.tombstone("session-1").orElseThrow().sessionId());
        assertTrue(reopened.load("session-1").isEmpty());
    }
}

